&lt;li&gt;Amazon API Gateway — &lt;a href="https://docs.aws.amazon.com/apigateway/" rel="noopener noreferrer"&gt;https://docs.aws.amazon.com/apigateway/&lt;/a&gt;
&lt;/li&gt;
&lt;li&gt;Amazon VPC — &lt;a href="https://docs.aws.amazon.com/vpc/" rel="noopener noreferrer"&gt;https://docs.aws.amazon.com/vpc/&lt;/a&gt;
&lt;/li&gt;
&lt;li&gt;AWS CodeBuild — &lt;a href="https://docs.aws.amazon.com/codebuild/" rel="noopener noreferrer"&gt;https://docs.aws.amazon.com/codebuild/&lt;/a&gt;
&lt;/li&gt;
&lt;li&gt;AWS CodePipeline — &lt;a href="https://docs.aws.amazon.com/codepipeline/" rel="noopener noreferrer"&gt;https://docs.aws.amazon.com/codepipeline/&lt;/a&gt;
&lt;/li&gt;
&lt;li&gt;AWS X-Ray — &lt;a href="https://docs.aws.amazon.com/xray/" rel="noopener noreferrer"&gt;https://docs.aws.amazon.com/xray/&lt;/a&gt;
&lt;/li&gt;
&lt;li&gt;Amazon Bedrock — &lt;a href="https://docs.aws.amazon.com/bedrock/" rel="noopener noreferrer"&gt;https://docs.aws.amazon.com/bedrock/&lt;/a&gt;
&lt;/li&gt;
